const TOPIC_HEX = {
  emerald: '#10b981', blue: '#3b82f6', violet: '#8b5cf6',
  orange: '#f97316', amber: '#f59e0b', cyan: '#06b6d4',
  indigo: '#6366f1', teal: '#14b8a6', rose: '#f43f5e',
  sky: '#0ea5e9', lime: '#84cc16',
};

function DiffBadge({ difficulty }) {
  const map = { Easy: '#10b981', Medium: '#f59e0b', Hard: '#ef4444' };
  const col = map[difficulty] || '#94a3b8';
  return (
    <span className="text-[0.65rem] font-bold px-1.5 py-0.5 rounded-full shrink-0"
      style={{ background: col + '22', color: col }}>
      {difficulty}
    </span>
  );
}

// DSA Sheet progress stored in localStorage independently of main tracker
function useDSAProgress() {
  const [progress, setProgress] = useState(() => {
    try { return JSON.parse(localStorage.getItem('dsa-sheet-progress') || '{}'); }
    catch { return {}; }
  });

  const setStatus = useCallback((key, status) => {
    setProgress(prev => {
      const next = { ...prev };
      if (status === null) delete next[key];
      else next[key] = status;
      localStorage.setItem('dsa-sheet-progress', JSON.stringify(next));
      return next;
    });
  }, []);

  return [progress, setStatus];
}

function lcSlug(title) {
  return title
    .toLowerCase()
    .replace(/['''`]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

function DSASheet({ onAddToTracker, existingTitles }) {
  const [activeTopicId, setActiveTopicId] = useState(DSA_SHEET[0].id);
  const [progress, setStatus] = useDSAProgress();
  const topic = DSA_SHEET.find(t => t.id === activeTopicId);
  const hex = TOPIC_HEX[topic.color] || '#8b5cf6';

  // Global stats across all topics
  const totalAll = DSA_SHEET.reduce((s, t) => s + t.patterns.reduce((ps, p) => ps + p.questions.length, 0), 0);
  const doneAll = Object.values(progress).filter(v => v === 'done').length;
  const pctAll = totalAll ? Math.round(doneAll / totalAll * 100) : 0;

  // Per-topic stats
  const topicTotal = topic.patterns.reduce((s, p) => s + p.questions.length, 0);
  const topicDone = topic.patterns.reduce((s, p) =>
    s + p.questions.filter(q => {
      const key = `${topic.id}__${p.name}__${q.title}`;
      return progress[key] === 'done';
    }).length, 0);

  const cycleStatus = (key, current) => {
    if (!current) setStatus(key, 'in-progress');
    else if (current === 'in-progress') setStatus(key, 'done');
    else setStatus(key, null);
  };

  return (
    <div>
      {/* Global progress bar */}
      <div className="glass rounded-2xl p-4 mb-6 flex items-center gap-4">
        <div className="flex-1">
          <div className="flex items-center justify-between mb-1.5">
            <span className="text-xs font-semibold t-muted uppercase tracking-wider">Overall DSA Progress</span>
            <span className="text-xs font-bold" style={{ color: 'var(--text-primary)' }}>{doneAll} / {totalAll}</span>
          </div>
          <div className="h-2 rounded overflow-hidden" style={{ background: 'var(--bg-secondary)' }}>
            <div className="h-full rounded bg-gradient-to-r from-violet-500 to-emerald-400 transition-all duration-500"
              style={{ width: `${pctAll}%` }} />
          </div>
        </div>
        <span className="text-2xl font-black tabular-nums text-violet-500">{pctAll}%</span>
      </div>

      {/* Topic pills */}
      <div className="flex flex-wrap gap-2 mb-6">
        {DSA_SHEET.map(t => {
          const c = TOPIC_HEX[t.color] || '#8b5cf6';
          const active = t.id === activeTopicId;
          const tTotal = t.patterns.reduce((s, p) => s + p.questions.length, 0);
          const tDone = t.patterns.reduce((s, p) =>
            s + p.questions.filter(q => progress[`${t.id}__${p.name}__${q.title}`] === 'done').length, 0);
          return (
            <button key={t.id} onClick={() => setActiveTopicId(t.id)}
              className="px-3.5 py-2 rounded-full text-xs font-semibold cursor-pointer transition-all duration-200 border flex items-center gap-1.5"
              style={active
                ? { background: c, borderColor: c, color: '#fff', boxShadow: `0 4px 14px ${c}44` }
                : { background: 'transparent', borderColor: 'var(--border-primary)', color: 'var(--text-muted)' }}>
              {t.icon} {t.topic}
              {tDone > 0 && (
                <span className="text-[0.6rem] font-bold px-1.5 py-0.5 rounded-full"
                  style={{ background: active ? 'rgba(255,255,255,0.25)' : c + '33', color: active ? '#fff' : c }}>
                  {tDone}/{tTotal}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {/* Topic header */}
      <div className="flex items-center gap-3 mb-5">
        <span className="text-2xl">{topic.icon}</span>
        <h2 className="text-xl font-bold" style={{ color: hex }}>{topic.topic}</h2>
        <div className="ml-auto flex items-center gap-3">
          <span className="text-xs font-bold" style={{ color: hex }}>{topicDone}/{topicTotal} done</span>
          <div className="w-24 h-1.5 rounded overflow-hidden" style={{ background: 'var(--bg-secondary)' }}>
            <div className="h-full rounded transition-all duration-500"
              style={{ width: `${topicTotal ? Math.round(topicDone / topicTotal * 100) : 0}%`, background: hex }} />
          </div>
        </div>
      </div>

      {/* Legend */}
      <div className="flex items-center gap-4 mb-4 text-[0.68rem] t-muted">
        <span>Click status circle to cycle:</span>
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-full border-2 inline-block" style={{ borderColor: 'var(--border-hover)' }} /> Todo</span>
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-full inline-block bg-amber-400" /> In Progress</span>
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-full inline-block bg-emerald-500" /> Done</span>
      </div>

      {/* Patterns */}
      <div className="flex flex-col gap-4">
        {topic.patterns.map(pattern => {
          const pDone = pattern.questions.filter(q =>
            progress[`${topic.id}__${pattern.name}__${q.title}`] === 'done').length;
          return (
            <div key={pattern.name} className="glass rounded-2xl overflow-hidden"
              style={{ borderColor: hex + '33' }}>
              <div className="px-5 py-3 flex items-center gap-2"
                style={{ background: hex + '11', borderBottom: `1px solid ${hex}22` }}>
                <span className="text-xs font-bold uppercase tracking-widest" style={{ color: hex }}>
                  {pattern.name}
                </span>
                <span className="text-[0.65rem] t-muted ml-auto">{pDone}/{pattern.questions.length} done</span>
              </div>
              <div className="divide-y" style={{ borderColor: 'var(--border-primary)' }}>
                {pattern.questions.map((q, i) => {
                  const key = `${topic.id}__${pattern.name}__${q.title}`;
                  const status = progress[key];
                  const alreadyAdded = q.lc && existingTitles.has(q.lc);
                  const lcUrl = q.lc
                    ? `https://leetcode.com/problems/${lcSlug(q.title)}/`
                    : `https://leetcode.com/search/?q=${encodeURIComponent(q.title)}`;
                  return (
                    <div key={i}
                      className="flex items-center gap-3 px-5 py-2.5 hover:bg-black/[0.02] dark:hover:bg-white/[0.02] transition-colors"
                      style={status === 'done' ? { opacity: 0.65 } : {}}>

                      {/* Status circle */}
                      <button
                        onClick={() => cycleStatus(key, status)}
                        title={!status ? 'Mark in progress' : status === 'in-progress' ? 'Mark done' : 'Clear'}
                        className="w-4 h-4 rounded-full border-2 shrink-0 transition-all duration-200 cursor-pointer hover:scale-110"
                        style={status === 'done'
                          ? { background: '#10b981', borderColor: '#10b981' }
                          : status === 'in-progress'
                          ? { background: '#f59e0b', borderColor: '#f59e0b' }
                          : { background: 'transparent', borderColor: 'var(--border-hover)' }}
                      />

                      {/* LC number */}
                      {q.lc
                        ? <span className="font-mono text-[0.65rem] t-muted w-8 shrink-0">#{q.lc}</span>
                        : <span className="w-8 shrink-0" />}

                      {/* Title */}
                      <span className="flex-1 text-sm" style={{
                        color: 'var(--text-primary)',
                        textDecoration: status === 'done' ? 'line-through' : 'none'
                      }}>{q.title}</span>

                      <DiffBadge difficulty={q.difficulty} />

                      {/* Open on LeetCode */}
                      <a href={lcUrl} target="_blank" rel="noreferrer"
                        title="Open on LeetCode"
                        className="p-1 rounded t-muted hover:text-amber-400 transition-colors shrink-0"
                        onClick={e => e.stopPropagation()}>
                        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                          <path d="M18 13v6a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2h6"/>
                          <polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/>
                        </svg>
                      </a>

                      {/* Add to main tracker */}
                      {onAddToTracker && (
                        <button
                          onClick={() => !alreadyAdded && onAddToTracker(q)}
                          disabled={alreadyAdded}
                          className="text-[0.65rem] font-semibold px-2.5 py-1 rounded-lg transition-all duration-200 shrink-0"
                          style={alreadyAdded
                            ? { background: '#10b98122', color: '#10b981', cursor: 'default' }
                            : { background: hex + '22', color: hex, cursor: 'pointer' }}
                          title={alreadyAdded ? 'Already in tracker' : 'Add to my tracker'}>
                          {alreadyAdded ? '✓ Added' : '+ Track'}
                        </button>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

const FILTERS = [
  { key: 'all', label: 'All' },
  { key: 'Easy', label: 'Easy' },
  { key: 'Medium', label: 'Medium' },
  { key: 'Hard', label: 'Hard' },
  { key: 'pending', label: 'Pending' },
  { key: 'done', label: 'Done' },
  { key: 'has-notes', label: 'Has Notes' },
  { key: 'has-solution', label: 'Has Solution' },
  { key: 'revision', label: 'Revision' },
  { key: 'confident', label: 'Confident' },
  { key: 'less-confident', label: 'Less Confident' },
  { key: 'must-revise', label: 'Must Revise' },
];

const READ_ONLY = false;

function App() {
  const [questions, setQuestions, dbLoaded] = useIndexedDB([]);
  const [filter, setFilter] = useState('all');
  const [search, setSearch] = useState('');
  const [openNoteId, setOpenNoteId] = useState(null);
  const [toast, setToast] = useState({ message: '', show: false });
  const [activeTab, setActiveTab] = useState('tracker');
  const fileInputRef = useRef(null);
  const [darkMode, setDarkMode] = useState(() => {
    const stored = localStorage.getItem('leetcode-theme');
    return stored ? stored === 'dark' : true; // default dark
  });

  useEffect(() => {
    document.documentElement.classList.toggle('dark', darkMode);
    localStorage.setItem('leetcode-theme', darkMode ? 'dark' : 'light');
  }, [darkMode]);

  const showToast = useCallback((msg) => {
    setToast({ message: msg, show: true });
    setTimeout(() => setToast(t => ({ ...t, show: false })), 2500);
  }, []);

  // Migrate old data
  useEffect(() => {
    const needsMigration = questions.some(q => q.notes === undefined || q.solution === undefined);
    if (needsMigration) {
      setQuestions(questions.map(q => ({
        ...q,
        notes: q.notes || '',
        solution: q.solution || '',
        language: q.language || 'python',
      })));
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const addQuestion = ({ number, title, difficulty, topic, notes }) => {
    const num = number || (questions.length ? Math.max(...questions.map(q => q.number || 0)) + 1 : 1);
    setQuestions([...questions, {
      id: Date.now(),
      number: num,
      title, difficulty, topic, notes,
      solution: '',
      language: 'python',
      done: false,
    }]);
    showToast('Problem added!');
  };

  const toggleDone = (id) => {
    setQuestions(questions.map(q => q.id === id ? { ...q, done: !q.done } : q));
    const q = questions.find(q => q.id === id);
    if (q && !q.done) showToast('Nice! Problem solved!');
  };

  const deleteQuestion = (id) => {
    setQuestions(questions.filter(q => q.id !== id));
    showToast('Problem removed');
  };

  const updateQuestion = (id, fields) => {
    setQuestions(questions.map(q => q.id === id ? { ...q, ...fields } : q));
  };

  const toggleMustRevise = (id) => {
    const q = questions.find(q => q.id === id);
    setQuestions(questions.map(q => q.id === id ? { ...q, mustRevise: !q.mustRevise } : q));
    showToast(q?.mustRevise ? 'Removed from must revise' : 'Added to must revise before interview!');
  };

  const addToRevision = (id) => {
    setQuestions(questions.map(q => q.id === id
      ? { ...q, revisionAddedAt: Date.now(), revisionDone: false }
      : q
    ));
    showToast('Added to revision list!');
  };

  const removeFromRevision = (id) => {
    setQuestions(questions.map(q => q.id === id
      ? { ...q, revisionAddedAt: null, revisionDone: false }
      : q
    ));
    showToast('Removed from revision');
  };

  const markRevisionDone = (id) => {
    setQuestions(questions.map(q => q.id === id
      ? { ...q, revisionDone: true, revisionAddedAt: null }
      : q
    ));
    showToast('Revision complete!');
  };

  // Revision items: due at 4 days and 7 days, stays until marked done
  const now = Date.now();
  const DAY = 86400000;
  const revisionItems = questions.filter(q => {
    if (!q.revisionAddedAt || q.revisionDone) return false;
    const elapsed = now - q.revisionAddedAt;
    return elapsed >= 4 * DAY; // show after 4 days
  }).map(q => {
    const elapsed = now - q.revisionAddedAt;
    const stage = elapsed >= 7 * DAY ? 2 : 1; // 1 = 4-day reminder, 2 = 7-day reminder
    return { ...q, revisionStage: stage };
  });

  const pendingRevisionCount = questions.filter(q => q.revisionAddedAt && !q.revisionDone).length;
  const mustReviseItems = questions.filter(q => q.mustRevise);

  const exportData = () => {
    const blob = new Blob([JSON.stringify(questions, null, 2)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'leetcode-tracker.json';
    a.click();
    showToast('Exported!');
  };

  const importData = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const data = JSON.parse(ev.target.result);
        if (Array.isArray(data)) {
          setQuestions(data.map(q => ({ ...q, notes: q.notes || '', solution: q.solution || '', language: q.language || 'python' })));
          showToast(`Imported ${data.length} problems!`);
        }
      } catch { showToast('Invalid file'); }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const loadPreset = () => {
    const existingNumbers = new Set(questions.map(q => q.number));
    const toAdd = BLIND75.filter(q => !existingNumbers.has(q.number));
    if (toAdd.length === 0) { showToast('All Blind 75 problems already added!'); return; }
    setQuestions(prev => [...prev, ...toAdd.map((q, i) => ({ ...q, id: Date.now() + i, done: false, solution: '', language: 'python' }))]);
    showToast(`Added ${toAdd.length} Blind 75 problems!`);
  };

  const unloadPreset = () => {
    const blind75Numbers = new Set(BLIND75.map(q => q.number));
    const remaining = questions.filter(q => !blind75Numbers.has(q.number));
    if (remaining.length === questions.length) { showToast('No Blind 75 problems found'); return; }
    if (!window.confirm(`Remove ${questions.length - remaining.length} Blind 75 problems?`)) return;
    setQuestions(remaining);
    showToast('Blind 75 problems removed');
  };

  // Stats
  const total = questions.length;
  const easy = questions.filter(q => q.difficulty === 'Easy').length;
  const medium = questions.filter(q => q.difficulty === 'Medium').length;
  const hard = questions.filter(q => q.difficulty === 'Hard').length;
  const done = questions.filter(q => q.done).length;
  const pct = total ? Math.round(done / total * 100) : 0;

  // Filter & search
  const filtered = questions.filter(q => {
    if (filter === 'Easy' || filter === 'Medium' || filter === 'Hard') {
      if (q.difficulty !== filter) return false;
    }
    if (filter === 'done' && !q.done) return false;
    if (filter === 'pending' && q.done) return false;
    if (filter === 'has-notes' && !(q.notes && q.notes.replace(/<[^>]*>/g, '').trim())) return false;
    if (filter === 'has-solution' && !(q.solution && q.solution.trim())) return false;
    if (filter === 'revision' && !q.revisionAddedAt) return false;
    if (filter === 'confident' && q.confidence !== 'confident') return false;
    if (filter === 'less-confident' && q.confidence !== 'less-confident') return false;
    if (filter === 'must-revise' && !q.mustRevise) return false;
    if (search) {
      const stripHtml = (html) => html ? html.replace(/<[^>]*>/g, ' ') : '';
      const hay = `${q.title} ${q.topic} ${q.number} ${stripHtml(q.notes)} ${q.solution || ''}`.toLowerCase();
      if (!hay.includes(search.toLowerCase())) return false;
    }
    return true;
  }).sort((a, b) => (a.number || 0) - (b.number || 0));

  // Escape to close notes
  useEffect(() => {
    const handler = (e) => { if (e.key === 'Escape') setOpenNoteId(null); };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, []);

  if (!dbLoaded) return (
    <div className="min-h-screen flex items-center justify-center">
      <div className="text-sm" style={{ color: 'var(--text-muted)' }}>Loading...</div>
    </div>
  );

  return (
    <>
      <BackgroundMesh />
      <div className="max-w-[1200px] mx-auto px-5 py-8 pb-16">
        {/* Header */}
        <header className="text-center mb-10">
          <div className="w-14 h-14 mx-auto mb-4 bg-gradient-to-br from-violet-500 to-violet-400 rounded-2xl
            flex items-center justify-center text-2xl shadow-lg animate-pulse-glow">
            &#x1F4BB;
          </div>
          <h1 className="text-4xl sm:text-5xl font-black tracking-tight leading-none bg-clip-text text-transparent"
            style={{ backgroundImage: `linear-gradient(to bottom right, var(--gradient-title-from), var(--gradient-title-via), var(--gradient-title-to))` }}>
            LeetCode Tracker
          </h1>
          <p className="t-muted mt-2">Must-solve problems for your coding interview</p>

          <div className="flex justify-center gap-2 mt-4 flex-wrap">
            {!READ_ONLY && <>
            <button onClick={exportData} className="px-3.5 py-2 btn-ghost rounded-xl t-muted text-xs font-medium cursor-pointer transition-all duration-200 backdrop-blur-xl
              hover:border-violet-500 hover:text-violet-400 hover:bg-violet-500/5 hover:-translate-y-0.5">
              <svg className="w-3.5 h-3.5 inline-block mr-1 -mt-0.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3"/>
              </svg>
              Export
            </button>
            <button onClick={() => fileInputRef.current?.click()} className="px-3.5 py-2 btn-ghost rounded-xl t-muted text-xs font-medium cursor-pointer transition-all duration-200 backdrop-blur-xl
              hover:border-violet-500 hover:text-violet-400 hover:bg-violet-500/5 hover:-translate-y-0.5">
              <svg className="w-3.5 h-3.5 inline-block mr-1 -mt-0.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M17 8l-5-5-5 5M12 3v12"/>
              </svg>
              Import
            </button>
            <input type="file" ref={fileInputRef} accept=".json" className="hidden" onChange={importData} />
            <button onClick={loadPreset} className="px-3.5 py-2 btn-ghost rounded-xl t-muted text-xs font-medium cursor-pointer transition-all duration-200 backdrop-blur-xl
              hover:border-violet-500 hover:text-violet-400 hover:bg-violet-500/5 hover:-translate-y-0.5">
              <svg className="w-3.5 h-3.5 inline-block mr-1 -mt-0.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/>
              </svg>
              Load Blind 75
            </button>
            <button onClick={unloadPreset} className="px-3.5 py-2 btn-ghost rounded-xl t-muted text-xs font-medium cursor-pointer transition-all duration-200 backdrop-blur-xl
              hover:border-red-500 hover:text-red-400 hover:bg-red-500/5 hover:-translate-y-0.5">
              <svg className="w-3.5 h-3.5 inline-block mr-1 -mt-0.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
              </svg>
              Unload Blind 75
            </button>
            </>}
            <button onClick={() => setDarkMode(!darkMode)}
              className="px-3.5 py-2 btn-ghost rounded-xl t-muted text-xs font-medium cursor-pointer transition-all duration-200 backdrop-blur-xl
              hover:border-violet-500 hover:text-violet-400 hover:bg-violet-500/5 hover:-translate-y-0.5">
              {darkMode ? (
                <svg className="w-3.5 h-3.5 inline-block mr-1 -mt-0.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/>
                </svg>
              ) : (
                <svg className="w-3.5 h-3.5 inline-block mr-1 -mt-0.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>
                </svg>
              )}
              {darkMode ? 'Light' : 'Dark'}
            </button>
          </div>
        </header>

        {/* Tab navigation */}
        <div className="flex gap-1 mb-8 p-1 rounded-2xl w-fit mx-auto" style={{ background: 'var(--bg-secondary)', border: '1px solid var(--border-primary)' }}>
          {[
            { key: 'tracker', label: '📋 My Tracker' },
            { key: 'dsa-sheet', label: '📖 DSA Sheet' },
          ].map(tab => (
            <button key={tab.key} onClick={() => setActiveTab(tab.key)}
              className="px-5 py-2 rounded-xl text-sm font-semibold transition-all duration-200 cursor-pointer"
              style={activeTab === tab.key
                ? { background: 'var(--bg-card)', color: 'var(--text-primary)', boxShadow: '0 2px 8px rgba(0,0,0,0.12)' }
                : { background: 'transparent', color: 'var(--text-muted)' }}>
              {tab.label}
            </button>
          ))}
        </div>

        {activeTab === 'dsa-sheet' ? (
          <DSASheet
            onAddToTracker={!READ_ONLY ? (q) => {
              const num = q.lc || null;
              const exists = num && questions.some(e => e.number === num);
              if (exists) { showToast('Already in tracker!'); return; }
              addQuestion({ number: num, title: q.title, difficulty: q.difficulty, topic: 'Array', notes: '' });
            } : null}
            existingTitles={new Set(questions.map(q => q.number).filter(Boolean))}
          />
        ) : (<>

        {/* Stats Grid */}
        <div className="grid grid-cols-5 gap-3 mb-6 max-sm:grid-cols-3 max-[480px]:grid-cols-2">
          <StatCard value={total} label="Total" colorClass="text-violet-600 dark:text-violet-400" accentColor="linear-gradient(90deg, #7c6af6, #a78bfa)" />
          <StatCard value={easy} label="Easy" colorClass="text-emerald-600 dark:text-emerald-400" accentColor="#34d399" />
          <StatCard value={medium} label="Medium" colorClass="text-amber-600 dark:text-amber-400" accentColor="#fbbf24" />
          <StatCard value={hard} label="Hard" colorClass="text-red-600 dark:text-red-400" accentColor="#f87171" />
          <StatCard value={done} label="Solved" colorClass="text-emerald-600 dark:text-emerald-400" accentColor="#34d399" />
        </div>

        {/* Progress Bar */}
        <div className="flex items-center gap-4 mb-6">
          <div className="flex-1 h-2 rounded overflow-hidden relative" style={{ background: 'var(--bg-secondary)' }}>
            <div
              className="h-full rounded bg-gradient-to-r from-violet-500 to-emerald-400 transition-all duration-600 ease-out relative shimmer"
              style={{ width: `${pct}%` }}
            />
          </div>
          <span className="text-sm font-bold text-violet-600 dark:text-violet-400 tabular-nums min-w-[45px] text-right">{pct}%</span>
        </div>

        {/* Add Form */}
        {!READ_ONLY && <AddForm onAdd={addQuestion} />}

        {/* Toolbar */}
        <div className="flex gap-2 mb-4 flex-wrap items-center">
          <div className="relative flex-1 min-w-[200px]">
            <svg className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 t-muted" viewBox="0 0 24 24" fill="none"
              stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <circle cx="11" cy="11" r="8" /><line x1="21" y1="21" x2="16.65" y2="16.65" />
            </svg>
            <input
              type="text"
              className="input-base pl-10"
              placeholder="Search problems or notes..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          {FILTERS.map(f => (
            <button
              key={f.key}
              onClick={() => setFilter(f.key)}
              className={`px-3.5 py-2 rounded-full text-xs font-semibold cursor-pointer transition-all duration-200 border
                ${filter === f.key
                  ? 'bg-violet-500 border-violet-500 text-white shadow-lg shadow-violet-500/25'
                  : 'btn-ghost t-muted hover:t-primary hover:bg-black/[0.04] dark:hover:bg-white/[0.04]'
                }`}
            >
              {f.label}
            </button>
          ))}
        </div>

        {/* Must Revise Before Interview */}
        {mustReviseItems.length > 0 && (
          <div className="mb-6 glass rounded-2xl p-5" style={{ borderColor: 'rgba(251,113,133,0.25)' }}>
            <div className="flex items-center gap-2 mb-4">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" stroke="none" className="text-rose-400">
                <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/>
              </svg>
              <h2 className="text-sm font-bold text-rose-400 uppercase tracking-widest">Must Revise Before Interview</h2>
              <span className="ml-auto text-xs t-muted">{mustReviseItems.length} problem{mustReviseItems.length !== 1 ? 's' : ''}</span>
            </div>
            <div className="flex flex-col gap-2">
              {mustReviseItems.map(q => {
                const diffClass = { Easy: 'text-emerald-500', Medium: 'text-amber-500', Hard: 'text-red-500' }[q.difficulty];
                return (
                  <div key={q.id} className="flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all duration-200 group"
                    style={{ background: 'var(--bg-input)', border: '1px solid var(--border-primary)' }}>
                    <input type="checkbox" className="custom-check" checked={q.done}
                      onChange={() => toggleDone(q.id)} />
                    <span className="font-mono text-xs t-muted">#{q.number}</span>
                    <span className="text-sm font-medium flex-1 truncate" style={{ color: 'var(--text-primary)', textDecoration: q.done ? 'line-through' : 'none' }}>{q.title}</span>
                    <span className={`text-[0.68rem] font-bold ${diffClass}`}>{q.difficulty}</span>
                    <button
                      onClick={() => toggleMustRevise(q.id)}
                      className="p-1 rounded t-muted hover:text-rose-400 transition-colors opacity-0 group-hover:opacity-100"
                      title="Remove from must revise"
                    >
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
                        <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
                      </svg>
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Revision Checklist */}
        {revisionItems.length > 0 && (
          <div className="mb-6 glass rounded-2xl p-5 border-amber-500/20">
            <div className="flex items-center gap-2 mb-4">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-amber-400">
                <circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/>
              </svg>
              <h2 className="text-sm font-bold text-amber-400 uppercase tracking-widest">Revision Due</h2>
              <span className="ml-auto text-xs t-muted">{revisionItems.length} problem{revisionItems.length !== 1 ? 's' : ''}</span>
            </div>
            <div className="flex flex-col gap-2">
              {revisionItems.map(q => {
                const daysAgo = Math.floor((now - q.revisionAddedAt) / DAY);
                return (
                  <div key={q.id} className="flex items-center gap-3 px-3 py-2.5 rounded-xl
                    hover:border-amber-500/20 transition-all duration-200 group"
                    style={{ background: 'var(--bg-input)', border: '1px solid var(--border-primary)' }}>
                    <input
                      type="checkbox"
                      className="custom-check"
                      checked={false}
                      onChange={() => markRevisionDone(q.id)}
                    />
                    <span className="font-mono text-xs t-muted">#{q.number}</span>
                    <span className="text-sm font-medium t-primary flex-1 truncate">{q.title}</span>
                    <span className={`text-[0.65rem] font-bold px-2 py-0.5 rounded-full
                      ${q.revisionStage === 2
                        ? 'bg-red-500/15 text-red-400 border border-red-500/30'
                        : 'bg-amber-500/15 text-amber-400 border border-amber-500/30'
                      }`}>
                      {q.revisionStage === 2 ? '7-day reminder' : '4-day reminder'}
                    </span>
                    <span className="text-[0.65rem] t-muted">{daysAgo}d ago</span>
                    <button
                      onClick={() => removeFromRevision(q.id)}
                      className="p-1 rounded t-muted hover:text-red-400 transition-colors opacity-0 group-hover:opacity-100"
                      title="Remove from revision"
                    >
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
                        <line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" />
                      </svg>
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Pending Revision (not yet due) */}
        {pendingRevisionCount > 0 && revisionItems.length === 0 && (
          <div className="mb-6 glass rounded-2xl px-5 py-3 flex items-center gap-2">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-amber-400/60">
              <circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/>
            </svg>
            <span className="text-xs t-muted">
              {pendingRevisionCount} problem{pendingRevisionCount !== 1 ? 's' : ''} scheduled for revision — reminders at 4 and 7 days
            </span>
          </div>
        )}

        {/* Problems List */}
        {filtered.length > 0 ? (
          <div className="flex flex-col gap-2">
            {filtered.map(q => (
              <ProblemCard
                key={q.id}
                question={q}
                onToggle={() => toggleDone(q.id)}
                onDelete={() => deleteQuestion(q.id)}
                onUpdate={(fields) => updateQuestion(q.id, fields)}
                onSetConfidence={(val) => updateQuestion(q.id, { confidence: val })}
                onToggleMustRevise={() => toggleMustRevise(q.id)}
                readOnly={READ_ONLY}
                isNoteOpen={openNoteId === q.id}
                onToggleNote={() => setOpenNoteId(openNoteId === q.id ? null : q.id)}
                onAddRevision={() => addToRevision(q.id)}
                onRemoveRevision={() => removeFromRevision(q.id)}
              />
            ))}
          </div>
        ) : (
          <div className="text-center py-20 t-muted">
            <div className="w-20 h-20 mx-auto mb-4 rounded-2xl flex items-center justify-center text-3xl" style={{ background: 'var(--bg-secondary)', border: '1px solid var(--border-primary)' }}>
              &#x1F4DD;
            </div>
            <h3 className="text-lg font-bold t-primary mb-1">No problems yet</h3>
            <p className="text-sm">Add your first LeetCode problem above or load the Blind 75 set!</p>
          </div>
        )}
        </>)}
      </div>

      <Toast message={toast.message} show={toast.show} />
    </>
  );
}

export default App;
